import { Controller, Get, HttpException, HttpStatus } from "@nestjs/common"

@Controller("cats")
export class CatsController {
    @Get()
    findAll() {
        throw new HttpException("Ruxsat yo'q", HttpStatus.FORBIDDEN)
    }
}
// GET /cats → 403  {"statusCode":403,"message":"Ruxsat yo'q"}

// 1) Matn: Nest o'zi statusCode qo'shadi
throw new HttpException("Hisob yopilgan", HttpStatus.FORBIDDEN)
// → {"statusCode":403,"message":"Hisob yopilgan"}

// 2) Obyekt: javob aynan siz yozgandek ketadi
throw new HttpException(
    { code: "NO_FUNDS", message: "Mablag' yetarli emas", balance: 15000 },
    HttpStatus.PAYMENT_REQUIRED,
)
// → {"code":"NO_FUNDS","message":"Mablag' yetarli emas","balance":15000}

throw new NotFoundException()
// → {"message":"Not Found","statusCode":404}

throw new NotFoundException("Kitob topilmadi")
// → {"message":"Kitob topilmadi","error":"Not Found","statusCode":404}

throw new BadRequestException(["ism bo'sh", "yosh 0 dan katta bo'lsin"])
// → {"message":["ism bo'sh","yosh 0 dan katta bo'lsin"],"error":"Bad Request","statusCode":400}

throw new ConflictException({ code: "EMAIL_TAKEN", message: "Email band" })
// → {"code":"EMAIL_TAKEN","message":"Email band"}   (obyekt — o'zi to'liq tana)

try {
    JSON.parse(fileText)
} catch (e) {
    throw new BadRequestException("Fayl formati noto'g'ri", {
        cause: e,                       // faqat logga — javobda ko'rinmaydi
        description: "JSON_PARSE_ERROR", // "error" maydoni shu bo'ladi
    })
}
// → {"message":"Fayl formati noto'g'ri","error":"JSON_PARSE_ERROR","statusCode":400}

// NestJS 12: mashina o'qiydigan kod
throw new BadRequestException("Parol juda oddiy", { errorCode: "WEAK_PASSWORD" })
// → {"message":"Parol juda oddiy","errorCode":"WEAK_PASSWORD","statusCode":400}

throw new Error("baza ulanishi uzildi")
// mijozga:  500  {"statusCode":500,"message":"Internal server error"}
// konsolda: [ExceptionsHandler] Error: baza ulanishi uzildi ... (stack trace)

export class OutOfStockException extends HttpException {
    constructor(product: string, available: number) {
        super(
            { error: "OUT_OF_STOCK", message: `${product} omborda yetarli emas`, available },
            HttpStatus.CONFLICT,
        )
    }
}

// ishlatilishi:
throw new OutOfStockException("noutbuk", 2)
// → 409 {"error":"OUT_OF_STOCK","message":"noutbuk omborda yetarli emas","available":2}

// NOTO'G'RI: 404 yo'qoladi, mijoz hamma narsani 500 deb ko'radi
try { return this.users.find(id) }
catch { throw new InternalServerErrorException("Xatolik") }

// TO'G'RI: HttpException o'zgarishsiz o'tadi, qolgani 500 bo'ladi
try { return this.users.find(id) }
catch (e) {
    if (e instanceof HttpException) throw e
    throw new InternalServerErrorException("Xatolik", { cause: e })
}

