import { Body, Controller, Injectable, Module, NotFoundException, Post, UnprocessableEntityException } from "@nestjs/common"

@Injectable()
class WalletService {
    private balances: Record<string, number> = { ali: 50_000 }

    withdraw(user: string, amount: number) {
        const balance = this.balances[user]
        if (balance === undefined) throw new NotFoundException(`${user} hamyoni topilmadi`)
        if (amount > balance) throw new UnprocessableEntityException(`Balans: ${balance}, so'ralgan: ${amount}`)
        this.balances[user] = balance - amount
        return { user, left: this.balances[user] }
    }
}

@Controller("wallet")
class WalletController {
    constructor(private wallet: WalletService) {}
    @Post("withdraw")
    withdraw(@Body() body: { user: string; amount: number }) {
        return this.wallet.withdraw(body.user, body.amount)     // try/catch shart emas
    }
}

@Module({ controllers: [WalletController], providers: [WalletService] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/wallet/withdraw", { user: "ali", amount: 20_000 })
    await http.post("/wallet/withdraw", { user: "ali", amount: 99_000 })
    await http.post("/wallet/withdraw", { user: "vali", amount: 1_000 })
    await http.close()
}
main()

