import { ArgumentsHost, Body, Catch, Controller, ExceptionFilter, Injectable, Module, Post, UseFilters } from "@nestjs/common"
import { InjectRepository, TypeOrmModule } from "@nestjs/typeorm"
import { Column, Entity, PrimaryGeneratedColumn, QueryFailedError, Repository } from "typeorm"

@Entity() class Tag {
    @PrimaryGeneratedColumn() id: number
    @Column({ unique: true }) name: string
}

@Catch(QueryFailedError)
class DbErrorFilter implements ExceptionFilter {
    catch(e: QueryFailedError, host: ArgumentsHost) {
        const unique = /UNIQUE/i.test(e.message)
        host.switchToHttp().getResponse().status(unique ? 409 : 500).json({
            statusCode: unique ? 409 : 500,
            message: unique ? "Bunday yozuv allaqachon mavjud" : "Baza xatosi",
        })
    }
}

@Injectable()
class TagsService {
    constructor(@InjectRepository(Tag) private readonly repo: Repository<Tag>) {}
    create(name: string) { return this.repo.save({ name }) }
}

@Controller("tags")
