class TagsController {
    constructor(private readonly s: TagsService) {}
    @Post() create(@Body("name") n: string) { return this.s.create(n) }
}

@Module({
    imports: [TypeOrmModule.forRoot({ type: "sqljs", entities: [Tag], synchronize: true }), TypeOrmModule.forFeature([Tag])],
