import { ArgumentsHost, Catch, Controller, ExceptionFilter, Get, HttpException, HttpStatus, Module } from "@nestjs/common"
import { APP_FILTER, HttpAdapterHost } from "@nestjs/core"

@Catch()
class CatchEverythingFilter implements ExceptionFilter {
    constructor(private readonly httpAdapterHost: HttpAdapterHost) {}

    catch(exception: unknown, host: ArgumentsHost): void {
        // httpAdapter konstruktorda hali tayyor bo'lmasligi mumkin — shu yerda olamiz
        const { httpAdapter } = this.httpAdapterHost
        const ctx = host.switchToHttp()
        const status = exception instanceof HttpException ? exception.getStatus() : HttpStatus.INTERNAL_SERVER_ERROR
        const body = { statusCode: status, path: httpAdapter.getRequestUrl(ctx.getRequest()) }
        httpAdapter.reply(ctx.getResponse(), body, status)
    }
}

