@Catch(HttpException)
class NormalizeFilter implements ExceptionFilter {
    catch(exception: HttpException, host: ArgumentsHost) {
        const status = exception.getStatus()
        const response = exception.getResponse()
        // matn bo'lsa o'zi, obyekt bo'lsa uning message maydoni
        const message = typeof response === "string" ? response : (response as { message?: string | string[] }).message ?? exception.message
