        catch(e: Error, h: ArgumentsHost) { h.switchToHttp().getResponse<Response>().status(500).json(prod ? { message: "Ichki xato" } : { message: e.message, hasStack: Boolean(e.stack) }) }
    }
    return F
}
@Controller("dev") @UseFilters(makeFilter(false)) class Dev { @Get() d() { throw new Error("db ulanmadi") } }
@Controller("prod") @UseFilters(makeFilter(true)) class Prod { @Get() p() { throw new Error("db ulanmadi") } }
@Module({ controllers: [Dev, Prod] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/dev")
    await http.get("/prod")
    await http.close()
}
main()

import { ArgumentsHost, Catch, ExceptionFilter, Controller, Get, Injectable, Module } from "@nestjs/common"
import { APP_FILTER } from "@nestjs/core"
import type { Request, Response } from "express"

@Injectable() class Sentry { sent: { msg: string; path: string }[] = []; capture(msg: string, path: string) { this.sent.push({ msg, path }) } }
@Catch() @Injectable() class ReportFilter implements ExceptionFilter {
    constructor(private s: Sentry) {}
    catch(e: Error, h: ArgumentsHost) { this.s.capture(e.message, h.switchToHttp().getRequest<Request>().url); h.switchToHttp().getResponse<Response>().status(500).json({ reported: true }) }
}
@Controller("r") class R { @Get() r() { throw new Error("kutilmagan null") } }
@Module({ controllers: [R], providers: [Sentry, { provide: APP_FILTER, useClass: ReportFilter }] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/r?x=1")
    console.log(http.app.get(Sentry).sent)
    await http.close()
}
main()

