import { ArgumentsHost, Catch, Controller, ExceptionFilter, Get, HttpException, Module, NotFoundException, Param, UseFilters } from "@nestjs/common"
import type { Request, Response } from "express"

const TITLES: Record<number, string> = { 400: "Bad Request", 404: "Not Found", 409: "Conflict" }

@Catch(HttpException)
class ProblemDetailsFilter implements ExceptionFilter {
    catch(exception: HttpException, host: ArgumentsHost) {
        const ctx = host.switchToHttp()
        const status = exception.getStatus()
        ctx.getResponse<Response>()
            .status(status)
            .type("application/problem+json")
            .json({
                type: "about:blank",
                title: TITLES[status] ?? "Error",
                status,
                detail: exception.message,
                instance: ctx.getRequest<Request>().originalUrl,
            })
    }
}

@Controller("orders")
@UseFilters(ProblemDetailsFilter)
class OrdersController {
    @Get(":id") one(@Param("id") id: string) { throw new NotFoundException(`Buyurtma #${id} topilmadi`) }
}

@Module({ controllers: [OrdersController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const res = await http.get("/orders/9")
    console.log("Content-Type:", res.headers.get("content-type"))
    await http.close()
}
main()

