import {
    ArgumentsHost, CanActivate, Catch, Controller, ExceptionFilter, ExecutionContext, Get, HttpException, Injectable, Module,
    Param, ParseIntPipe, UseFilters, UseGuards,
} from "@nestjs/common"
import type { Response } from "express"

@Injectable()
class AllowGuard implements CanActivate {
    canActivate(context: ExecutionContext) {
        return context.switchToHttp().getRequest().headers["x-allow"] === "1"     // false → ForbiddenException
    }
}

@Catch(HttpException)
class ControllerFilter implements ExceptionFilter {
    catch(exception: HttpException, host: ArgumentsHost) {
        const status = exception.getStatus()
        host.switchToHttp().getResponse<Response>().status(status).json({ handledBy: "controller filter", status })
    }
}

@Controller("secure")
@UseGuards(AllowGuard)
@UseFilters(ControllerFilter)
class SecureController {
    @Get(":id") one(@Param("id", ParseIntPipe) id: number) { return { id } }
}

@Module({ controllers: [SecureController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/secure/5")
    await http.get("/secure/abc", { "x-allow": "1" })
    await http.get("/secure/5", { "x-allow": "1" })
    await http.close()
}
main()

