import { ArgumentsHost, Catch, Controller, ExceptionFilter, Get, HttpException, Module, NotFoundException } from "@nestjs/common"
import type { Response } from "express"

const logged: string[] = []
@Catch() class Only500Log implements ExceptionFilter {
    catch(e: unknown, h: ArgumentsHost) {
        const status = e instanceof HttpException ? e.getStatus() : 500
        if (status >= 500) logged.push((e as Error).message)
        h.switchToHttp().getResponse<Response>().status(status).json({ status })
    }
}
@Controller() class C { @Get("nf") nf() { throw new NotFoundException() } @Get("boom") b() { throw new Error("DB tushib qoldi") } }
@Module({ controllers: [C] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalFilters(new Only500Log()))
    await http.get("/nf")
    await http.get("/boom")
    console.log("log'ga tushgan:", logged)
    await http.close()
}
main()

